const items = $input.all();

return items.map((item, i) => {
  let src = null;
  let prep = {};
  try {
    const matched = $('Prepare Summary Payload').itemMatching(i);
    if (matched && matched.json) {
      src = matched.json.original || matched.json;
      prep = matched.json;
    }
  } catch (e) {}

  if (!src) {
    try {
      const first = $('Prepare Summary Payload').first();
      if (first && first.json) {
        src = first.json.original || first.json;
        prep = first.json;
      }
    } catch (e) {}
  }
  if (!src) src = item.json.original || item.json;

  const raw = (item.json && item.json.message && item.json.message.content)
    ? item.json.message.content
    : (item.json && item.json.content)
      ? item.json.content
      : (item.json && item.json.response)
        ? item.json.response
        : (item.json && item.json.choices && item.json.choices[0] ? item.json.choices[0].message.content : '');

  let parsed = null;
  if (typeof raw === 'string') {
    try {
      const start = raw.indexOf('{');
      const end = raw.lastIndexOf('}');
      if (start !== -1 && end > start) {
        parsed = JSON.parse(raw.slice(start, end + 1));
      }
    } catch (e) {}
  } else if (raw && typeof raw === 'object') {
    parsed = raw;
  }

  let summaryEn = (parsed && parsed.en && parsed.en.summary) ? String(parsed.en.summary).trim() : '';
  let summaryId = (parsed && parsed.id && parsed.id.summary) ? String(parsed.id.summary).trim() : '';

  if (!summaryEn && !summaryId && typeof raw === 'string') {
    const s = raw.trim();
    if (s.length >= 20 && !s.startsWith('{')) {
      summaryEn = s.trim();
      summaryId = s.trim();
    }
  }

  let relevanceEn = (parsed && parsed.en && parsed.en.relevance) ? String(parsed.en.relevance).trim() : '';
  let relevanceId = (parsed && parsed.id && parsed.id.relevance) ? String(parsed.id.relevance).trim() : '';
  if (!relevanceId && relevanceEn) relevanceId = relevanceEn;
  if (!relevanceEn && relevanceId) relevanceEn = relevanceId;
  if (relevanceId) relevanceId = cleanRelevanceToId(relevanceId);

  const relevanceStatus = (parsed && parsed.relevance_status)
    ? String(parsed.relevance_status).trim().toUpperCase()
    : ((relevanceEn || relevanceId) && !/\b(tidak relevan|kurang relevan|bukan bukti|tidak berkaitan|tidak berhubungan|tidak mencakup|tidak memenuhi|not relevant|not directly relevant|irrelevant|unrelated|does not relate|does not satisfy|does not demonstrate|does not align)\b/i.test(relevanceId + ' ' + relevanceEn) ? 'RELEVANT' : 'NOT_RELEVANT');
  const ok = summaryEn.length >= 20 || summaryId.length >= 20;

  const warnings = (src.warnings || []).slice();
  if (prep && prep.summary_input_clipped) warnings.push('summary_from_partial_text');

  return { json: Object.assign({}, src, {
    content_summary: summaryEn,
    content_summary_id: summaryId,
    content_relevance: relevanceEn,
    content_relevance_id: relevanceId,
    content_relevance_status: relevanceStatus,
    summary_status: ok ? 'ok' : 'empty',
    summary_source: 'llm_generated',
    warnings,
  })};
});

