const items = $input.all();

return items.map((item, i) => {
  const src = $('Prepare Describe Payload').itemMatching(i).json;
  const raw = (item.json && item.json.message && item.json.message.content)
    ? item.json.message.content
    : (item.json && item.json.content)
      ? item.json.content
      : (item.json && item.json.response)
        ? item.json.response
        : (item.json && item.json.choices && item.json.choices[0] ? item.json.choices[0].message.content : '');

  let rawText = '';
  if (typeof raw === 'string') rawText = raw;
  else if (Array.isArray(raw)) rawText = raw.map(p => p.text || '').join('\n');
  rawText = rawText.trim();

  // Extract the { en: {summary, relevance}, id: {summary, relevance} } object from the
  // model's reply (tolerate stray text/code fences).
  let descEn = '', descId = '', relEn = '', relId = '', relStatus = '';
  try {
    const start = rawText.indexOf('{');
    const end = rawText.lastIndexOf('}');
    const parsed = JSON.parse(rawText.slice(start, end + 1));
    descEn = ((parsed.en && parsed.en.summary) || '').trim();
    descId = ((parsed.id && parsed.id.summary) || '').trim();
    relEn = ((parsed.en && parsed.en.relevance) || '').trim();
    relId = ((parsed.id && parsed.id.relevance) || '').trim();
    if (!relId && relEn) relId = relEn;
    if (relId) relId = cleanRelevanceToId(relId);
    relStatus = (parsed.relevance_status || (parsed.id && parsed.id.status) || (parsed.en && parsed.en.status) || '').toUpperCase().trim();
  } catch (e) {
    // Couldn't parse the structured JSON — fall back to treating the raw reply as an
    // English-only description with no relevance note.
    descEn = rawText;
  }

  if (!relStatus && (relEn || relId)) {
    const combined = (relId + ' ' + relEn).toLowerCase();
    relStatus = /\b(tidak relevan|kurang relevan|bukan bukti|tidak berkaitan|tidak berhubungan|tidak mencakup|tidak memenuhi|not relevant|not directly relevant|irrelevant|unrelated|does not relate|does not satisfy|does not demonstrate|does not align)\b/.test(combined) ? 'NOT_RELEVANT' : 'RELEVANT';
  }
  const desc = descEn || descId;
  const usage = item.json.usage || {};

  return { json: {
    file_id: src.file_id, file_name: src.file_name,
    file_category: 'IMAGE',
    content_mode: desc.length >= 30 ? 'visual' : 'none',
    has_text: false,
    extraction_method: 'ollama_vision_describe',
    text: '', visual_description: desc, page_count: 1,
    content_summary: descEn,
    content_summary_id: descId,
    content_relevance: relEn,
    content_relevance_id: relId,
    content_relevance_status: relStatus,
    result_id: src.result_id || null, file_path: src.file_path || null, locale: src.locale || 'en',
    control_code: src.control_code || '', control_title: src.control_title || '', control_requirement: src.control_requirement || '',
    requires_human_review: true,
    warnings: (src.warnings || []).concat('content_is_model_observation'),
    tokens_used: usage.total_tokens || null,
  }};
});

